<script setup lang="ts">
import { computed, shallowRef } from 'vue'
import { useExploreRequest } from '../composables/useExploreRequest'
import DistributionBars from '../components/DistributionBars.vue'
interface Sample {state:{status:string;updatedAt:string|null;samplingRule:string};size:number;tags:Record<string,number>;formats:Record<string,number>;years:Record<string,number>;subjects:{id:string;name:string;fetchedAt:string}[];notice:string}
const {data,pending,error,retry}=useExploreRequest<Sample>(computed(()=>'/community/overview')),limit=shallowRef(20)
const buckets=(rows:Record<string,number>|undefined)=>Object.entries(rows||{}).map(([label,count])=>({label,count})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label)).slice(0,20)
const tags=computed(()=>buckets(data.value?.tags)),formats=computed(()=>buckets(data.value?.formats)),years=computed(()=>buckets(data.value?.years))
</script>
<template><section class="page-intro"><h1>Bangumi 社区样本观察</h1><p>看看当前已获取的作品样本有哪些共同特征。样本范围与全体观众偏好分别解释。</p></section><p v-if="pending" class="feedback" role="status">正在整理公开样本…</p><p v-if="error" class="feedback error" role="alert">{{ error }} <button @click="retry">重试</button></p><template v-if="data"><p class="notice">{{ data.notice }} 样本 {{ data.size }} 部；{{ data.state.samplingRule }}</p><p v-if="!data.size" class="empty-state">尚未准备样本。关联账号后，可在观看偏好的推荐区更新公共候选。</p><div v-else class="community-charts"><section class="panel"><h2>样本标签 · 前20项</h2><DistributionBars :items="tags" label="样本标签"/></section><section class="panel"><h2>动画形式</h2><DistributionBars :items="formats" label="样本形式"/></section><section class="panel"><h2>发行年份 · 前20项</h2><DistributionBars :items="years" label="样本发行年份"/></section></div><details class="panel"><summary>核对样本清单与采集时间</summary><div v-for="subject in data.subjects.slice(0,limit)" :key="subject.id" class="data-row"><RouterLink :to="`/explore/anime/${subject.id}`">{{ subject.name }}</RouterLink><small>{{ new Date(subject.fetchedAt).toLocaleString('zh-CN') }}</small></div><button v-if="limit<data.subjects.length" @click="limit+=20">再展开20部</button></details></template></template>
<style scoped>.community-charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.community-charts h2{font-size:18px}.panel summary{cursor:pointer}.data-row small{font-size:11px;color:#71856f}@media(max-width:650px){.community-charts{grid-template-columns:1fr}.data-row{flex-wrap:wrap}}</style>
